from collections import Counter
def transform(g):
    h,w=len(g),len(g[0])
    bg=Counter(x for row in g for x in row).most_common(1)[0][0]
    cnt=Counter(x for row in g for x in row if x!=bg)
    out=[row[:] for row in g]
    # find color with >=2 cells collinear on a diagonal (largest such line)
    best=None
    for col,n in cnt.items():
        if n<2: continue
        pts=[(r,c) for r in range(h) for c in range(w) if g[r][c]==col]
        for keyf in (lambda p:p[0]+p[1], lambda p:p[0]-p[1]):
            lines={}
            for p in pts: lines.setdefault(keyf(p),[]).append(p)
            for k,lp in lines.items():
                if len(lp)>=2 and (best is None or len(lp)>len(best[0])):
                    best=(lp,col,keyf)
    if not best: return out
    lp,col,keyf=best
    r0,c0=lp[0]
    if keyf is None or (r0+c0)==keyf(lp[0]) and keyf(lp[1])==r0+c0:
        d=(1,-1)
    if r0-c0==lp[1][0]-lp[1][1]: d=(1,1)
    else: d=(1,-1)
    for r,c in lp:
        r,c=r+d[0],c+d[1]
        while 0<=r<h and 0<=c<w and out[r][c]==bg:
            out[r][c]=col; r+=d[0]; c+=d[1]
        r,c=lp[0][0]-d[0],lp[0][1]-d[1]  # fix below
        break
    # extend both directions properly from each line cell's ends
    out=[row[:] for row in g]
    ends=[min(lp),max(lp)]
    if d==(1,-1): ends=[min(lp,keyf),max(lp,keyf)][::-1] if keyf(lp[0])==r0+c0 else [min(lp,keyf),max(lp,keyf)]
    ends=sorted(lp,key=keyf)
    for e in (ends[0],ends[-1]):
        for dd in (d,(-d[0],-d[1])):
            r,c=e[0]+dd[0],e[1]+dd[1]
            while 0<=r<h and 0<=c<w and out[r][c]==bg:
                out[r][c]=col; r+=dd[0]; c+=dd[1]
    return out

